// FirstEnabledTransition is Appendix D selectTransitions, the half only this
// document can answer: the first of state's own transitions, in document order,
// that event enables and whose guard holds. The engine walks the atomic states
// and their ancestors and keeps the ordered set; the null event asks for
// eventless transitions.
//line idler.scxml:5
func (p *IdlerPolicy) FirstEnabledTransition(state IdlerState, event IdlerEvent, engine *sce.Engine[IdlerState, IdlerEvent]) (sce.EnabledTransition[IdlerState, sce.HistoryID], bool) {
	switch state {
	case IdlerStateIdling:
		if event == IdlerEventSceTestSnapshot {
			// docs/SCE_TEST_PROFILE.md §12.3: a branch of the test component,
			// guarded by its cond and then its match on the round's snapshot.
			if p.sceTestContext.SnapshotPresent("peer") {
				return sce.EnabledTransition[IdlerState, sce.HistoryID]{
					Source:          state,
					Targets:         transitionTargetsOfIdler[state][0],
					TransitionIndex: 0,
					HasActions:      true,
					IsInternal:      false,
				}, true
			}
		}
	}
	return sce.EnabledTransition[IdlerState, sce.HistoryID]{}, false
}

